import { CAPABILITIES_LOT_1 } from '../completion/capabilitiesLot1.js';
import { area, beam, buff, cleanse, defend, guard, heal, hit, shot } from './rules.js';

// Every row chooses its three actions explicitly. The existing completion
// record provides bibliography and universe identity, never an inferred move.
// Effects, timing and protection remain gameplay adaptations of those roles.
const AUTHORED = 'authored-universe-canon';
const kit = (id, simple, secondary, defense, sourceReference, identityBasis = 'canonical-role') => {
  const source = CAPABILITIES_LOT_1[id];
  if (!source) throw new Error(`Unknown lot 1 ability source: ${id}`);
  return {
    sourceHeroId: id, universe: source.universe, sourceWork: source.sourceWork,
    sourceReference, sourceUrl: source.sourceUrl || null,
    identityBasis, canonicalVerified: false, networkVerified: false, gameplayAdaptation: true,
    simple, secondary: { cd: 6, ...secondary }, defense
  };
};

