  saitama_opm: kit('saitama_opm', hit('Normal Punch de Saitama'), hit('Consecutive Normal Punches', 1.9), defend('Écart sans effort de Saitama', 0.6), 'Saitama utilise coups ordinaires et séries de coups ; tous les dégâts restent bornés pour le crossover et ne prétendent pas sa puissance narrative.'),
  genos_opm: kit('genos_opm', hit('Poing mécanique de Genos'), beam('Canon thermique du bras de Genos', 1.9), defend('Bras cybernétiques en couverture'), 'Genos combine force mécanique et énergie thermique de ses bras ; ces capacités proviennent de son corps cyborg.'),
  tatsumaki_opm: kit('tatsumaki_opm', shot('Objet déplacé par Tatsumaki'), area('Pression télékinétique de Tatsumaki', 1.9), defend('Barrière psychique de Tatsumaki', 0.6), 'Tatsumaki manipule la matière et crée des protections psychiques ; projection, pression et barrière adaptent son propre pouvoir.'),
  shinichi_migi: kit('shinichi_migi', hit('Estoc du bras de Migi'), hit('Enchaînement des lames de Migi', 1.8), defend('Interception de la lame parasite', 0.5), 'Migi transforme le bras droit de Shinichi pour attaquer et intercepter ; aucun parasite supplémentaire ni arme à feu n’est inventé.'),
  satomi_murano: kit('satomi_murano', buff('Appeler Shinichi par son nom'), buff('Rappeler le lien humain de Satomi'), defend('Rester à l’abri près des compagnons'), 'Satomi reste une amie humaine de Shinichi ; ses gestes relationnels ne reçoivent aucun pouvoir de parasite.'),
  mamoru_uda: kit('mamoru_uda', buff('Prévenir Shinichi avec Uda'), guard('Interposer la forme protectrice de Jaw'), defend('Reculer derrière l’interception de Jaw'), 'Jaw est le parasite de la mâchoire d’Uda et le défend ; la protection vient de ce duo précis, sans transplantation de Migi.'),
  jack_sparrow_potc: kit('jack_sparrow_potc', hit('Estoc du sabre de Jack'), hit('Feinte improvisée du duel de Jack', 1.7), defend('Esquive du capitaine Sparrow'), 'Dans La Malédiction du Black Pearl, Jack combat à l’épée par ruse et improvisation ; il ne maîtrise pas le Kraken.'),
  elizabeth_swann_potc: kit('elizabeth_swann_potc', buff('Invoquer le droit de pourparlers'), guard('Négocier le passage d’Elizabeth'), defend('Repli hors de la ligne des sabres'), 'L’Elizabeth du premier film utilise le droit de pourparlers et cherche à protéger les autres ; la table ne lui prête pas une magie pirate.'),
  will_turner_potc: kit('will_turner_potc', hit('Taille du forgeron Turner'), hit('Riposte d’escrime de Will', 1.8), defend('Parade à l’épée forgée de Will', 0.5), 'Will est un forgeron et bretteur dans le premier film ; les gestes gardent son entraînement et son arme physique.'),
  viking_kok: kit('viking_kok', hit('Percussion au bouclier d’Ursa'), hit('Charge physique de la guerrière viking', 1.8), defend('Bouclier d’Ursa interposé', 0.6), 'Le segment viking de Killer of Killers montre Ursa combattant avec son bouclier ; aucune technologie Yautja ne lui est ajoutée.'),
  ninja_kok: kit('ninja_kok', hit('Taille au sabre du shinobi'), hit('Estoc de l’embuscade du segment japonais', 1.8), defend('Parade silencieuse du combattant japonais'), 'Le personnage de rôle Shadow Ninja du pack suit le segment japonais de Killer of Killers ; sabre et déplacement, sans ninjutsu surnaturel inventé.'),
