  prey_2006_enisi: kit('prey_2006_enisi', buff('Enisi explique la prochaine épreuve'), guard('Guidage du grand-père dans le passage spirituel'), defend('Se retirer dans le lieu du conseil'), 'Enisi conseille Tommy et le guide dans les épreuves spirituelles ; il ne reçoit pas le Spirit Bow du protagoniste.'),
  psy_avatar: kit('psy_avatar', buff('Gangnam Style — premier pas du cheval'), buff('Gangnam Style — reprise du refrain'), defend('Retour au repère chorégraphique de PSY'), 'L’avatar représente la performance dansée de PSY ; le mouvement n’est pas une aptitude de combat de la personne réelle.'),
  gangnam_dancer: kit('gangnam_dancer', buff('Décompte du danseur de Gangnam'), buff('Relais du pas du cheval'), defend('Espacement de la formation dansée'), 'Gangnam Dancer est un rôle chorégraphique du catalogue ; le kit garde exclusivement la coordination musicale.', AUTHORED),
  kpop_crowd_psy: kit('kpop_crowd_psy', buff('Réponse du public au refrain de PSY'), guard('Laisser libre le passage du concert'), defend('Recul de la ligne du public'), 'Le public allié du pack encourage et sécurise le concert ; aucune attaque de foule réelle n’est créée.', AUTHORED),
  john_rambo: kit('john_rambo', hit('Coup rapproché du soldat Rambo'), shot('Flèche de l’arc de Rambo', 1.8), defend('Repli derrière la végétation'), 'First Blood Part II montre Rambo avec son arc et ses aptitudes militaires ; les gestes ne détaillent aucune fabrication d’arme.'),
  sam_trautman: kit('sam_trautman', buff('Trautman vérifie la liaison radio'), buff('Transmettre la consigne d’extraction'), defend('Couvert du poste radio du colonel'), 'Trautman est le supérieur et contact radio de Rambo ; il coordonne plutôt que dupliquer les exploits physiques du soldat.'),
  co_bao: kit('co_bao', shot('Arme de terrain de Co Bao'), guard('Guider Rambo vers la voie d’exfiltration'), defend('Couvert de Co Bao sur le trajet'), 'Co Bao aide Rambo à s’exfiltrer au Vietnam et utilise une arme conventionnelle ; son renseignement reste lié au terrain.'),
  shilo_repo: kit('shilo_repo', buff('Shilo exprime son autonomie'), buff('Seventeen — reprise de Shilo'), defend('Pause hors de la scène de GeneCo'), 'Shilo chante Seventeen et cherche son autonomie dans Repo! ; elle ne reçoit ni aptitude de chirurgie ni arme génétique.'),
  repo_man: kit('repo_man', hit('Lame du Repo Man'), hit('Geste rapproché de Nathan Wallace', 1.8), defend('Recul derrière le manteau du Repo Man'), 'Nathan Wallace porte des instruments de Repo Man dans l’opéra fictionnel ; les frappes sont abstraites et non graphiques, sans description de procédure.'),
